<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { Cloud, RefreshCw, ShieldCheck, Download, Monitor, Pause, Play, ArrowRight, Link, Unplug } from 'lucide-vue-next'
import ConfirmDialog from './components/ConfirmDialog.vue'
import { api, post } from './api'
import { parseRecovery, syncConnection, type DataSource } from './workspaceSetup'
const props=defineProps<{user:any,desktop:boolean}>()
const emit=defineEmits<{ready:[]}>()
const sync=ref<any>({status:'loading'}),upgrade=ref<any>(null),busy=ref(false),error=ref(''),notice=ref('')
const tab=ref('sync'),preview=ref<any>(null),devices=ref<any>(null),conflicts=ref<any[]>([]),points=ref<any[]>([])
const form=ref({backend:'hub',url:'',device_name:'我的设备',create:false,username:'',email:'',password:'',token:'',grant:'',allow_private:false,recovery:''})
const setup=ref<any>(null),source=ref<DataSource|''>(''),recoveryFile=ref('')
const dataSources:{id:DataSource,title:string,description:string}[]=[
  {id:'independent',title:'全新开始 / 独立使用',description:'在当前环境研究，之后随时可以接入同步。'},
  {id:'desktop',title:'从已有桌面版同步',description:'将另一台电脑上的 StockAI 3.2 个人资料带到这里。'},
  {id:'web',title:'从已有 Web / NAS 同步',description:'将另一套 StockAI Web 站点的个人资料带到这里。'},
  {id:'publish',title:'创建空间供其他环境加入',description:'上传本端资料，再让其他电脑或站点加入同一个空间。'},
  {id:'legacy',title:'从旧版本地版迁移',description:'旧源码版 8765 的 data 目录，由管理员离线迁移。'},
]
const remoteSource=computed(()=>['desktop','web','publish'].includes(source.value))
let recoveryRead=0
const pointPreview=ref<any>(null),migrationOpen=ref(false),migrationPreview=ref<any>(null),confirmText=ref('');let confirmResolve:((answer:boolean)=>void)|null=null
async function guard(){if(!dirty.value)return true;confirmText.value='当前页面有尚未处理的输入。确认离开并清除这些临时输入？';return new Promise<boolean>(r=>confirmResolve=r)}
function settle(answer:boolean){confirmText.value='';confirmResolve?.(answer);confirmResolve=null}

const recovery=ref(''),password=ref(''),grant=ref<any>(null),confirmation=ref(''),manifest=ref(''),manual=ref('')
const transferTargets=ref<Record<string,string>>({})
const caps=ref<{daily:number|null,monthly:number|null}>({daily:null,monthly:null})
const states:Record<string,string>={unconfigured:'尚未配置',loading:'正在读取',binding_pending:'连接尚未确认，请重试预览',configured:'等待首次合并',synced:'已同步',syncing:'继续传输中',conflicts:'有冲突待处理',waiting_dependencies:'等待依赖完整',paused:'已暂停',offline:'离线 · 本地资料已保留',auth_failed:'凭据失效',revoked:'设备已撤销',storage_full:'远端空间不足',incompatible:'服务不兼容',error:'同步未完成'}
const upgradeStates:Record<string,string>={planned:'计划已准备',downloading:'正在下载',uploading:'正在导入',download_paused:'下载已暂停',download_failed:'下载未完成',verified:'安装包已验证',awaiting_operator:'等待服务器运维执行',preflight_blocked:'预检存在阻断项',waiting_confirmation:'预检完成，等待本人确认',exit_requested:'正在退出并交接升级',backup:'正在验证加密恢复点',preparing:'正在准备程序',migrating:'正在迁移和检查',switching:'正在切换程序',succeeded:'升级成功',rolling_back:'正在恢复',rolled_back:'已恢复原版本',manual_recovery:'需要处理恢复阻断',cancelled:'已取消',failed:'失败'}
const checkStates:Record<string,string>={never_checked:'尚未检查',checking:'正在检查',check_failed:'检查失败',up_to_date:'当前通道已是最新',available:'有可用版本',download_available:'GitHub 有新版本可下载',download_current:'当前通道暂无更高版本',download_unavailable:'当前通道暂无适用发行包'}
const updateSourceConfigured=computed(()=>upgrade.value?.source_configured??(upgrade.value?.check?.error!=='SOURCE_UNCONFIGURED'))
const updateCheckLabel=computed(()=>updateSourceConfigured.value?(checkStates[upgrade.value?.check.status]||upgrade.value?.check.status):'在线更新未配置')
const githubUpdates=computed(()=>upgrade.value?.source_kind==='github')
const releasePage=computed(()=>upgrade.value?.release_page||'https://github.com/EdgarLi-Xun/StockAI/releases')
const checkErrors:Record<string,string>={SOURCE_UNCONFIGURED:'尚未配置可信更新源',NETWORK:'暂时无法连接更新服务，请检查网络后重试',RATE_LIMITED:'更新请求已被限流，请稍后重试',GITHUB_METADATA:'GitHub 返回的版本资料无效，请稍后重试',GITHUB_INCOMPLETE:'GitHub 发行记录尚未读取完整，请前往发布页核对',UNTRUSTED:'发布清单身份或签名验证失败',EXPIRED:'发布清单已过期',REPLAY:'检测到过期或重复使用的发布资料',TARGET:'发行包与当前程序不匹配'}
const tx=computed(()=>upgrade.value?.transaction)
const configured=computed(()=>sync.value.status!=='unconfigured'&&sync.value.status!=='loading')
const date=(value:string)=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—'
async function act(fn:()=>Promise<any>,message='') {if(busy.value)return;busy.value=true;error.value='';notice.value='';try{const value=await fn();if(message)notice.value=message;return value}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function load(){sync.value=await api('/me/sync');if(props.user.role==='admin')upgrade.value=await api('/admin/upgrades')}
async function loadSetup(){setup.value=await api('/me/workspace-setup');if(!source.value&&setup.value.source)source.value=setup.value.source}
function changeSource(value:DataSource){source.value=value;recoveryRead++;form.value.password='';form.value.token='';form.value.grant='';form.value.recovery='';recoveryFile.value='';preview.value=null;error.value='';notice.value=''}
async function startIndependent(){await act(async()=>{setup.value=await post('/me/workspace-setup',{source:'independent'});emit('ready')})}
async function checkLegacy(){await act(async()=>{await Promise.all([load(),loadSetup()]);notice.value=setup.value.has_data?'已检测到个人资料，可进入研究工作台核对。':'尚未检测到迁入的个人资料，请核对离线迁移结果。'})}
async function readRecoveryFile(event:Event){
  const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return
  const current=++recoveryRead;form.value.recovery='';recoveryFile.value=''
  await act(async()=>{try{if(file.size>1024*1024)throw new Error('恢复材料文件超过 1 MiB，请核对是否选中了正确的 JSON 文件。');const text=await file.text();if(current!==recoveryRead)return;parseRecovery(text);form.value.recovery=text;recoveryFile.value=file.name;notice.value='恢复材料已读取，验证连接后仍需检查并确认合并预览。'}finally{input.value=''}})
}
async function connect(){await act(async()=>{try{const value=migrationOpen.value?{...form.value,create:true,recovery:undefined}:syncConnection(source.value,form.value);if(migrationOpen.value){migrationPreview.value=await post('/me/sync/migration/preview',value)}else{setup.value=await post('/me/workspace-setup',{source:source.value});sync.value=await post('/me/sync/connect',value);preview.value=await post('/me/sync/preview')}}finally{form.value.password='';form.value.token='';form.value.grant='';form.value.recovery='';recoveryFile.value=''}},'连接已验证。请检查合并预览，确认后才导入资料。')}
async function merge(){await act(async()=>{sync.value=await post('/me/sync/run',{preview_id:preview.value?.id});preview.value=null;await details()},'本轮同步已完成，未完成的批次会继续保留。')}
async function details(){const value=await Promise.all([api('/me/sync/devices'),api('/me/sync/conflicts'),api('/me/sync/checkpoints')]);devices.value=value[0];conflicts.value=value[1];points.value=value[2];caps.value={...devices.value.limits}}
async function recoveryExport(){await act(async()=>{try{recovery.value=JSON.stringify(await post('/me/sync/recovery',{password:password.value}),null,2)}finally{password.value=''}},'请单独保管恢复材料；其中包含同步解密密钥。')}
function saveRecovery(){const blob=URL.createObjectURL(new Blob([recovery.value],{type:'application/json'}));const a=document.createElement('a');a.href=blob;a.download='StockAI-同步恢复材料.json';a.click();setTimeout(()=>URL.revokeObjectURL(blob),1000)}
async function prepare(){await act(async()=>{await post('/admin/upgrades/plan',manifest.value?{envelope:JSON.parse(manifest.value)}:{});manifest.value='';await load()},'已准备具体升级计划。')}
async function prepareLocal(){await act(async()=>{await post('/admin/upgrades/plan',{local:true});await load()},'已准备本机安装计划。请下载或导入同名安装包，核对通过后仍需确认才会退出并安装。')}
async function cleanup(){const value=await act(()=>post('/admin/upgrades/cleanup',{confirmation:'清理已过期的升级缓存'}));if(value){await load();notice.value=value.status==='waiting'?value.reason:'已清理 '+value.files.length+' 处过期升级缓存，释放 '+(value.bytes/1024/1024).toFixed(1)+' MB。'}}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file||!tx.value)return;await act(async()=>{for(let offset=0;offset<file.size;offset+=3*1024*1024){const bytes=new Uint8Array(await file.slice(offset,offset+3*1024*1024).arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));await post('/admin/upgrades/'+tx.value.id+'/upload',{offset,data:btoa(binary)})}await load()},'离线包已导入并完成长度和摘要验证。')}
const client=crypto.randomUUID();let timer:ReturnType<typeof setInterval>
const dirty=computed(()=>!!(form.value.password||form.value.token||form.value.grant||password.value||form.value.recovery||manifest.value||manual.value))
defineExpose({guard,dirty})
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>{void act(()=>Promise.all([load(),loadSetup()]));window.addEventListener('beforeunload',beforeUnload);timer=setInterval(()=>{void load().catch(()=>{});void post('/me/client-state',{id:client,dirty:dirty.value}).catch(()=>{})},10000)})
onBeforeUnmount(()=>{recoveryRead++;clearInterval(timer);window.removeEventListener('beforeunload',beforeUnload);void post('/me/client-state',{id:client,dirty:false}).catch(()=>{});recovery.value='';form.value.password='';form.value.recovery='';form.value.grant='';password.value='';settle(false)})
</script>

<template>
  <main class="personal-content system-settings">
    <div class="page-heading"><div><p class="eyebrow">工作区设置</p><h1>同步与版本</h1><p>{{ desktop?'本机独立工作区 · 桌面与本机 Web 共享资料':'独立 Web 站点 · 本人资料与账号隔离' }}</p></div><ShieldCheck :size="28" /></div>
    <div class="button-row system-tabs"><button :class="tab==='sync'?'primary':'secondary'" @click="tab='sync'"><Cloud :size="16" />个人资料同步</button><button :class="tab==='upgrade'?'primary':'secondary'" @click="tab='upgrade'"><Monitor :size="16" />关于与升级</button></div>
    <p v-if="error" role="alert" class="public-message error">{{ error }}</p><p v-if="notice" role="status" class="public-message success">{{ notice }}</p>
    <template v-if="tab==='sync'">
      <section v-if="setup&&!configured&&sync.status!=='loading'" class="panel data-source-panel">
        <div class="panel-heading"><div><h2>{{ setup.required?'这个环境的数据从哪里来？':'选择数据来源' }}</h2><p>可以从已有环境带入个人资料，也可以独立使用。{{ setup.has_data?'当前已有的资料会保留。':'新环境不会按登录邮箱自动取回其他环境的数据。' }}</p></div><Download :size="23" /></div>
        <fieldset class="data-source-options"><legend class="source-legend">选择本环境的开始方式</legend><label v-for="option in dataSources" :key="option.id" :class="['data-source-option',{selected:source===option.id}]"><input v-model="source" type="radio" name="data-source" :value="option.id" :disabled="busy" @change="changeSource(option.id)" /><span><strong>{{ option.id==='independent'&&setup.has_data?'继续使用当前资料':option.title }}</strong><small>{{ option.description }}</small></span></label></fieldset>
        <div v-if="source==='independent'" class="source-next"><p>{{ setup.has_data?'保留当前资料，继续在此环境独立研究。':'从空白研究空间开始，之后可在“同步与版本”重新选择数据来源。' }}</p><button class="primary" :disabled="busy" @click="startIndependent">{{ setup.has_data?'保留资料并进入工作台':'全新开始' }}<ArrowRight :size="16" /></button></div>
        <div v-else-if="source==='desktop'||source==='web'" class="source-next"><h3>先在{{ source==='desktop'?'原电脑':'原 Web / NAS' }}准备资料</h3><ol><li>打开“同步与版本”。若尚未绑定，先创建 Hub / WebDAV 空间，再完成首次上传和所有剩余批次。</li><li>验证原账号密码并导出“同步恢复材料”。使用 Hub 时，再生成一个十分钟内有效的设备授权码。</li><li>在下方填写同一个同步服务地址和凭据，选择恢复材料文件，验证后检查合并预览。</li></ol><p>同步服务地址是 Hub 或 WebDAV 的 HTTPS 地址。两端需要加入同一个空间；原研究工作台的网址不能直接作为 Hub 地址。</p></div>
        <div v-else-if="source==='publish'" class="source-next"><p>在下方选择 Hub / WebDAV 并创建空间。首次上传完成后，在本页导出恢复材料，供其他环境加入。</p></div>
        <div v-else-if="source==='legacy'" class="source-next"><h3>旧源码版数据迁移</h3><p v-if="!setup.legacy_available">{{ setup.legacy_reason }}</p><template v-else><p>将旧版完整 data 目录放到服务器并只读挂载。管理员停止应用后，使用现有离线迁移命令导入到当前账号；迁移会先创建加密恢复点，再校验并复制资料。</p><code>python -m backend.cloud.cli migrate --source &lt;旧版data目录&gt; --admin-id {{ user.id }}</code><p>Docker 部署需在应用容器中运行此命令，并将旧目录只读挂载。完成后启动服务并重新登录，资料会出现在当前账号下。</p></template><button class="secondary" :disabled="busy" @click="checkLegacy">检查迁移结果</button></div>
      </section>
      <section v-if="configured||remoteSource" class="panel personal-form"><div class="panel-heading"><div><h2>{{ states[sync.status]||sync.status }}</h2><p v-if="configured">{{ sync.device_name }} · {{ sync.backend==='hub'?'独立 Hub':'WebDAV' }} · 最近成功 {{ date(sync.last_success) }}</p><p v-else>{{ source==='publish'?'创建空间并上传本端资料':'加入已有空间，将个人资料同步到当前环境' }}</p></div><Cloud :size="23" /></div>
        <div v-if="configured" class="system-summary"><span><b>{{ sync.pending_upload||0 }}</b> 待发送</span><span><b>{{ sync.conflicts||0 }}</b> 待处理冲突</span><span v-if="sync.missing_dependencies">{{ sync.missing_dependencies }} 项等待依赖</span><span>空间 {{ sync.space_id }}</span></div>
        <div v-if="configured" class="button-row"><button class="primary" :disabled="busy||sync.status==='paused'" @click="act(async()=>{preview=await post('/me/sync/preview')})"><RefreshCw :size="15" />预览并同步</button><button class="secondary" :disabled="busy" @click="act(async()=>{sync=await post('/me/sync/pause',{paused:sync.status!=='paused'})})"><component :is="sync.status==='paused'?Play:Pause" :size="15" />{{ sync.status==='paused'?'恢复同步':'暂停同步' }}</button><button class="secondary" :disabled="busy" @click="act(details)">设备、冲突与恢复点</button><small v-if="sync.metrics">本轮 {{ sync.metrics.uploaded_operations }} 项 · {{ sync.metrics.elapsed_seconds }} 秒 · 上传 {{ ((sync.metrics.uploaded_bytes||0)/1024).toFixed(1) }} KB</small><label class="check-label"><input type="checkbox" :checked="sync.automatic" @change="act(async()=>{sync=await post('/me/sync/pause',{paused:sync.status==='paused',automatic:($event.target as HTMLInputElement).checked})})" />自动同步</label></div>
        <button v-if="configured&&sync.status==='paused'" class="text-button" @click="migrationOpen=!migrationOpen">更换同步后端</button><form v-if="((!configured&&remoteSource)||migrationOpen)&&sync.status!=='loading'" class="form-grid" @submit.prevent="connect">
          <label>同步后端<select v-model="form.backend"><option value="hub">StockAI Hub</option><option value="webdav">WebDAV / NAS</option></select></label><label>设备名称<input v-model="form.device_name" maxlength="80" required /></label>
          <label class="span-two">Hub / WebDAV 的 HTTPS 服务根地址<input v-model="form.url" type="url" placeholder="https://sync.example.com" required /></label><p v-if="!migrationOpen" class="personal-note span-two">{{ source==='publish'?'本次会创建一个新的同步空间。':'本次会加入恢复材料对应的已有空间。' }}</p>
          <label>{{ form.backend==='hub'?'Hub 账号邮箱':'WebDAV 用户名' }}<input v-if="form.backend==='hub'" v-model="form.email" type="email" autocomplete="username" required /><input v-else v-model="form.username" autocomplete="username" required /></label><label>服务密码<input v-model="form.password" type="password" autocomplete="current-password" required /></label>
          <template v-if="source!=='publish'&&!migrationOpen"><label v-if="form.backend==='hub'">十分钟单次设备授权码<input v-model="form.grant" required autocomplete="off" /></label><label class="span-two recovery-file">选择原设备导出的同步恢复材料文件<input type="file" accept=".json,application/json" :disabled="busy" @change="readRecoveryFile" /><small v-if="recoveryFile">已读取：{{ recoveryFile }}</small></label><label class="span-two">本人恢复材料（也可粘贴 JSON）<textarea v-model="form.recovery" rows="4" required spellcheck="false" autocomplete="off" /></label></template>
          <label class="check-label span-two"><input v-model="form.allow_private" type="checkbox" />连接本人信任的内网 NAS（Web 站点还需管理员配置可访问网段）</label><p class="personal-note span-two">凭据加密保存在当前运行端。同步包不包含模型 Key、登录会话或模型数据授权。接收到的规则、任务和委托不会自动执行。</p><button class="primary" :disabled="busy"><Link :size="16" />{{ migrationOpen?'验证目标并预览迁移':'验证身份并连接' }}</button>
        </form>
      </section>
      <section v-if="sync.migration" class="panel personal-form"><h2>后端迁移等待继续</h2><p>已准备目标 {{ sync.migration.target }}，旧后端保持暂停。确认后继续同一计划，不切回双写。</p><button class="primary" :disabled="busy" @click="act(async()=>{sync=await post('/me/sync/migration/confirm',{id:sync.migration.id});await load()})">继续此迁移</button></section><section v-if="migrationPreview" class="panel personal-form"><h2>更换同步后端预览</h2><p>{{ migrationPreview.source }} → {{ migrationPreview.target }} · {{ migrationPreview.url }}</p><p>迁移 {{ migrationPreview.objects }} 项，保留 {{ migrationPreview.tombstones }} 条删除标记和共享用量。封存旧空间后启用目标；其他设备需重新授权。</p><button class="primary" :disabled="busy" @click="act(async()=>{sync=await post('/me/sync/migration/confirm',{id:migrationPreview.id});migrationPreview=null;migrationOpen=false;devices=null},'迁移完成。自动同步保持关闭，请核对后开启。')">确认迁移此计划</button></section><section v-if="preview" class="panel personal-form"><h2>首次或本轮合并预览</h2><p>本机待发 {{ preview.local_pending }} 项，远端 {{ preview.remote_objects }} 项，删除标记 {{ preview.remote_tombstones }} 项。合并保留独立资料，并发改动进入冲突处理。</p><p>首次合并会先创建本人的加密恢复点。</p><div class="button-row"><button class="primary" :disabled="busy" @click="merge">确认此预览并合并 <ArrowRight :size="16" /></button><button class="secondary" @click="preview=null">取消</button></div></section>
      <section v-if="devices" class="panel personal-list"><h2>设备与执行归属</h2><div v-for="(device,id) in devices.devices" :key="id" class="personal-list-row"><span><b>{{ device.name }}</b><small>{{ id===devices.current?'当前设备':'' }} · 代次 {{ device.generation }}</small></span><span class="tag">{{ device.revoked?'已撤销':devices.executor.device===id?'自动执行端':'资料同步端' }}</span><button v-if="!device.revoked&&id!==devices.current" class="text-button" :disabled="busy" @click="act(async()=>{await post('/me/sync/devices/revoke',{device:id});await details()},'已撤销设备。建议轮换同步密钥并重新分发恢复材料。')">撤销设备</button><button v-if="!device.revoked&&devices.executor.device!==id" class="text-button" :disabled="busy" @click="act(async()=>{await post('/me/sync/executor',{device:id});await details()})">指定为执行端</button></div><p class="personal-note">在途或结果不确定的动作会阻止执行端切换。模拟账本独立持有写入权，接收端保持只读。</p><button v-if="sync.backend==='hub'" class="secondary" :disabled="busy" @click="act(async()=>{grant=await post('/me/sync/grant')})">生成新设备授权码</button><p v-if="grant" class="invite-result">{{ grant.code }}<small>有效至 {{ date(grant.expires) }}，单次使用。加入端仍需本人恢复材料及同一 Hub 账号。</small></p>
        <div v-for="(account,id) in devices.accounts" :key="id" class="system-subsection"><h3>{{ account.name||'模拟账户' }}</h3><p>{{ account.frozen?'账本已冻结，请保留分支核对':'写入端：'+(devices.devices[account.device]?.name||'未知设备') }} · 代次 {{ account.generation }}</p><div v-if="account.local_id&&account.device===devices.current&&!account.frozen" class="button-row"><select v-model="transferTargets[id]"><option disabled value="">选择新的写入端</option><option v-for="(device,deviceId) in devices.devices" :key="deviceId" :value="deviceId" :disabled="device.revoked||deviceId===devices.current">{{ device.name }}</option></select><button class="secondary" :disabled="busy||!transferTargets[id]" @click="act(async()=>{await post('/me/sync/account-transfer',{account_id:account.local_id,device:transferTargets[id]});await details()},'账本写入权已按新代次转移。')">在线转移此账本写入权</button></div></div><div v-if="devices.usage" class="system-subsection"><h3>已确认的共享调用计数</h3><p>今日 {{ devices.usage.daily }} 次 · 本月 {{ devices.usage.monthly }} 次 · 本机尚未确认 {{ devices.usage.unconfirmed_local }} 次。计数包含在途和结果不确定的调用，不代表供应商余额或费用。</p></div><div class="form-grid system-subsection"><label>共享每日调用上限（留空为不限）<input v-model.number="caps.daily" type="number" min="0" /></label><label>共享每月调用上限（留空为不限）<input v-model.number="caps.monthly" type="number" min="0" /></label></div><button class="secondary" :disabled="busy" @click="act(async()=>{await post('/me/sync/limits',{daily:caps.daily==null||String(caps.daily)===''?null:Number(caps.daily),monthly:caps.monthly==null||String(caps.monthly)===''?null:Number(caps.monthly)});await details()})">提交共享上限</button><p v-if="devices.limits_proposal" class="personal-note">新上限待所有有效设备确认后生效；离线设备尚未确认，当前不宣称新上限已全局启用。</p>
      </section>
      <section v-if="conflicts.length" class="panel personal-list"><h2>保留双方的冲突</h2><article v-for="conflict in conflicts" :key="conflict.id" class="system-conflict"><b>{{ conflict.kind }} · {{ date(conflict.created_at) }}</b><details><summary>查看基线与双方内容</summary><pre>{{ JSON.stringify({baseline:conflict.base,local:conflict.local,remote:conflict.remote},null,2) }}</pre></details><div v-if="!['account','report','backtest'].includes(conflict.kind)" class="button-row"><button class="secondary" :disabled="busy" @click="act(async()=>{await post('/me/sync/conflicts/'+conflict.id,{choice:'local'});await details()})">以本机内容生成新版本</button><button class="secondary" :disabled="busy" @click="act(async()=>{await post('/me/sync/conflicts/'+conflict.id,{choice:'remote'});await details()})">以远端内容生成新版本</button></div><div v-else><p>账本与不可变归档已隔离，保留原分支供核对，不合并现金或覆盖归档。</p><button class="secondary" :disabled="busy" @click="act(async()=>{await post('/me/sync/conflicts/'+conflict.id+'/fork',{choice:'local'});await details()},'已建立独立分支副本，保留来源记录。')">将本机分支保留为独立副本</button></div></article></section>
      <section v-if="configured" class="panel personal-form"><h2>恢复材料与本机绑定</h2><p>恢复密钥与登录密码分开保管。导出材料能解密此空间，请保存到本人安全位置。</p><div class="form-grid"><label>当前账号密码<input v-model="password" type="password" autocomplete="current-password" /></label><button class="secondary" :disabled="busy||!password" @click="recoveryExport">验证并导出恢复材料</button></div><div v-if="recovery" class="button-row"><button class="primary" @click="saveRecovery"><Download :size="16" />保存恢复材料</button><button class="secondary" @click="recovery=''">隐藏材料</button></div><div v-for="point in points" :key="point.id" class="personal-list-row"><span>{{ point.reason }}</span><span>{{ date(point.created_at) }}</span><span>{{ point.objects }} 项 · 已加密</span><button class="text-button" :disabled="busy" @click="act(async()=>{pointPreview=await post('/me/sync/checkpoints/'+point.id+'/preview')})">预览恢复</button></div><div v-if="pointPreview" class="system-subsection"><p>可将 {{ pointPreview.allowed.length }} 项恢复为新版本；{{ pointPreview.skipped.length }} 项保留当前删除标记、账本或不可变归档。</p><button class="secondary" :disabled="busy" @click="act(async()=>{await post('/me/sync/checkpoints/'+pointPreview.point+'/restore',{confirmation:pointPreview.id});pointPreview=null;await details()},'已创建恢复版本，等待下次同步。')">确认此预览并恢复为新版本</button></div><details class="system-subsection"><summary>轮换密钥或解除绑定</summary><p>轮换后其他设备需要新的恢复材料；解除绑定保留本机资料和待发密文，不删除远端空间。</p><input v-model="confirmation" placeholder="输入操作对应的完整确认语句" /><div class="button-row"><button class="secondary" :disabled="busy||confirmation!=='轮换密钥并重新授权其他设备'" @click="act(async()=>{await post('/me/sync/rotate',{confirmation});confirmation=''},'密钥已轮换，请重新导出材料并重新授权其他设备。')">轮换密钥并重新授权其他设备</button><button class="secondary danger-text" :disabled="busy||confirmation!=='解除本机绑定并保留本地资料'" @click="act(async()=>{await post('/me/sync/unbind',{confirmation});devices=null;await load()})"><Unplug :size="15" />解除本机绑定并保留本地资料</button><button class="secondary danger-text" :disabled="busy||confirmation!=='删除我的远端同步资料'" @click="act(async()=>{const result=await post('/me/sync/delete',{confirmation});notice=result.status==='pending'?'远端清理仍在等待，尚未完成删除。':'远端业务密文已删除，最新控制记录继续保留。';await load()})">删除我的远端同步资料</button></div></details></section>
    </template>
    <template v-else>
      <section class="panel personal-form">
        <div class="panel-heading"><div><h2>StockAI {{ upgrade?.current_version||'3.2.0-preview.1' }}</h2><p>{{ desktop?'Windows 桌面与附属 Web':'独立 Web 研究服务' }}</p></div><Monitor :size="26" /></div>
        <p v-if="user.role!=='admin'">版本升级由本站管理员管理。个人资料同步由本人独立控制。</p>
        <template v-if="upgrade">
          <div class="button-row">
            <span class="tag">{{ upgrade.settings.channel==='stable'?'稳定通道':'预览通道' }}</span>
            <span role="status">{{ updateCheckLabel }}</span>
            <button class="secondary" :disabled="busy||!updateSourceConfigured" @click="act(async()=>{await post('/admin/upgrades/check');await load()})"><RefreshCw :size="15" />检查更新</button>
            <a class="text-button" :href="releasePage" rel="noopener noreferrer">前往发布页手动下载</a>
          </div>
          <p v-if="!updateSourceConfigured" class="personal-note">此版本未配置在线更新服务，自动检查和下载暂不可用。请前往项目发布页手动下载新版本。当前程序和个人资料可继续使用。</p>
          <p v-else-if="upgrade.check.error" class="personal-note">检查未完成：{{ checkErrors[upgrade.check.error]||upgrade.check.error }}。当前程序继续可用。</p>
          <p v-if="githubUpdates&&desktop&&upgrade.form==='exe'" class="personal-note">更新来源：GitHub Releases。本机可以下载安装包，或导入已经下载的同名 Setup.exe，并用发布页上的 SHA-256 核对后安装。这不是发布者签名。安装前仍需确认，工作区不会重置。</p>
          <p v-else-if="githubUpdates" class="personal-note">更新来源：GitHub Releases。当前程序不会从这里自动替换服务，请前往发布页手动下载对应安装包。自动下载与安装仍需要经过签名的发布源。</p>
          <p v-if="upgrade.check.last_attempt" class="personal-note">最近检查 {{ date(upgrade.check.last_attempt) }} · 最近成功 {{ date(upgrade.check.last_success) }}</p>
          <label>更新通道<select :value="upgrade.settings.channel" @change="act(async()=>{await api('/admin/upgrades/settings',{method:'PUT',body:JSON.stringify({channel:($event.target as HTMLSelectElement).value})});await load()})"><option value="stable">稳定版</option><option value="preview">预览版</option></select></label>
          <label class="check-label"><input type="checkbox" :disabled="busy||!updateSourceConfigured" :checked="upgrade.settings.automatic_check" @change="act(async()=>{await api('/admin/upgrades/settings',{method:'PUT',body:JSON.stringify({automatic_check:($event.target as HTMLInputElement).checked})});await load()})" />启动时和每 24 小时检查更新</label>
          <label class="check-label"><input type="checkbox" :disabled="busy||!updateSourceConfigured||githubUpdates" :checked="upgrade.settings.automatic_download" @change="act(async()=>{await api('/admin/upgrades/settings',{method:'PUT',body:JSON.stringify({automatic_download:($event.target as HTMLInputElement).checked})});await load()})" />自动下载已验签的可用更新，安装仍需确认</label>
          <p>安装前需明确确认计划。服务器无执行器时仅准备计划，等待运维执行。</p>
          <p v-if="upgrade.check.release">{{ githubUpdates?'GitHub 发行版本':'可用版本' }} {{ upgrade.check.release.version }} · {{ upgrade.check.release.component }}</p>
          <div v-if="upgrade.check.status==='download_available'" class="button-row"><button v-if="desktop&&upgrade.form==='exe'" class="primary" :disabled="busy" @click="prepareLocal">准备本机下载安装</button><a class="text-button" :href="upgrade.check.release.download_url" rel="noopener noreferrer"><Download :size="15" />在浏览器中下载 {{ upgrade.check.release.asset_name }}</a><a class="text-button" :href="upgrade.check.release.release_url" rel="noopener noreferrer">查看发布说明</a></div>
          <p v-if="githubUpdates&&upgrade.check.status==='download_unavailable'&&upgrade.settings.channel==='stable'" class="personal-note">稳定通道尚无适用的发行包，可切换预览通道查看预览版本。</p>
          <button v-if="upgrade.check.status==='available'" class="primary" :disabled="busy" @click="prepare">查看升级计划</button>
          <details class="system-subsection"><summary>导入离线签名清单</summary><p>离线升级同样需要已安装的可信发布根和对应组件的签名清单。安装包摘要校验不能代替发布者签名。</p><textarea v-model="manifest" rows="5" placeholder="粘贴签名清单 JSON" spellcheck="false" /><button class="secondary" :disabled="busy||!manifest" @click="prepare">验证签名并准备计划</button></details>
        </template>
      </section>
      <section v-if="tx" class="panel personal-form"><h2>{{ upgradeStates[tx.status]||tx.status }}</h2><p>{{ tx.component }} · {{ tx.from_version }} → {{ tx.target_version }} · {{ upgrade.form }}</p><p>计划所属工作区：{{ tx.workspace }}</p><p v-if="tx.trust==='github-sha256'">安装包只从 GitHub 发布页下载。也可导入已经下载的同名 Setup.exe，程序按发布页 SHA-256 核对；确认前不会替换正在运行的程序。</p><p>安装包 {{ (tx.release.package.size/1024/1024).toFixed(1) }} MB · 数据迁移 {{ tx.release.migration||(tx.trust==='github-sha256'?'沿用桌面工作区，由新程序打开':'依签名计划检查') }}</p><button v-if="tx.status==='downloading'" class="secondary" @click="post('/admin/upgrades/'+tx.id+'/cancel').then(()=>notice='下载暂停请求已提交。').catch(e=>error=e.message)">暂停下载</button><progress v-if="tx.total" :value="tx.downloaded" :max="tx.total" /><p v-if="tx.error" role="alert">{{ tx.error }}</p><ul v-if="tx.blockers?.length"><li v-for="blocker in tx.blockers" :key="blocker">{{ blocker }}</li></ul><div class="button-row"><button v-if="['planned','download_failed','download_paused'].includes(tx.status)" class="primary" :disabled="busy" @click="act(async()=>{await post('/admin/upgrades/'+tx.id+'/download');await load()})"><Download :size="15" />下载并验证</button><label v-if="['planned','uploading'].includes(tx.status)" class="secondary">导入对应离线安装包<input type="file" :disabled="busy" @change="upload" /></label><button v-if="['verified','awaiting_operator','preflight_blocked','waiting_confirmation'].includes(tx.status)" class="secondary" :disabled="busy" @click="act(async()=>{await post('/admin/upgrades/'+tx.id+'/preflight');await load()})">运行安装预检</button><button v-if="['planned','verified','awaiting_operator','preflight_blocked','waiting_confirmation','download_failed','download_paused'].includes(tx.status)" class="text-button" :disabled="busy" @click="act(async()=>{await post('/admin/upgrades/'+tx.id+'/cancel');await load()})">取消此计划</button></div><p v-if="tx.operator_command">等待运维在服务所在机器停服后执行：<code>{{ tx.operator_command }}</code></p><template v-if="desktop&&tx.status==='waiting_confirmation'&&!tx.blockers?.length"><label class="check-label"><input type="checkbox" v-model="confirmation" true-value="确认安装并重启" false-value="" />我已保存编辑并确认安装 {{ tx.target_version }}，允许退出桌面后重启</label><button class="primary" :disabled="busy||confirmation!=='确认安装并重启'" @click="act(async()=>{await post('/admin/upgrades/'+tx.id+'/execute',{confirmation:tx.confirmation});await load()})">确认安装并重启桌面</button></template></section>
      <section v-if="upgrade" class="panel personal-form"><h2>安装缓存与恢复点</h2><p>清理已结束且超过 30 天的安装缓存和数据检查点，保留当前程序及可用旧代码。检查点过期后会标明不能据此恢复。未完成事务、个人资料和待同步记录继续保留。</p><button class="secondary" :disabled="busy" @click="cleanup">清理已过期的升级缓存</button><p v-if="upgrade.cache_cleanup">最近检查 {{ date(upgrade.cache_cleanup.checked_at) }} · 已释放 {{ (upgrade.cache_cleanup.bytes/1024/1024).toFixed(1) }} MB</p></section>
      <section v-if="upgrade?.history?.length" class="panel personal-list"><h2>升级与恢复记录</h2><div v-for="entry in upgrade.history" :key="entry.id" class="personal-list-row"><span>{{ entry.from_version }} → {{ entry.target_version }}</span><span>{{ upgradeStates[entry.status]||entry.status }}<small v-if="entry.recovery_available===false">检查点已过期，不能据此恢复</small></span><span>{{ date(entry.updated_at) }}</span></div></section>
    </template>
    <ConfirmDialog :message="confirmText" @choose="settle" />
  </main>
</template>
